import{_ as i,o as e,c as a,aw as n}from"./chunks/framework.DLufY-ao.js";const _=JSON.parse('{"title":"Интеграционные тесты","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/testing/testing/pyramid/integration-test.md","filePath":"wiki/dev-commit/testing/testing/pyramid/integration-test.md"}'),o={name:"wiki/dev-commit/testing/testing/pyramid/integration-test.md"};function r(l,t,s,d,m,c){return e(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="интеграционные-тесты" tabindex="-1">Интеграционные тесты <a class="header-anchor" href="#интеграционные-тесты" aria-label="Permalink to &quot;Интеграционные тесты&quot;">​</a></h1><ul><li><strong>Интеграционные тесты (сервисные / компонентные тесты)</strong> на соответствие требований проверяется интеграция модулей/компонентов, их взаимодействие между собой, а также интеграция подсистем в одну общую систему. Это может быть набор классов/методов/функций, модуль, подсистема или даже само приложение. Для интеграционного тестирования используются компоненты, уже проверенные с помощью модульного тестирования, которые группируются в множества. Данные множества проверяются в соответствии с планом тестирования, составленным для них, а объединяются они через свои интерфейсы. Так как модули соединяются между собой с помощью предусмотренных реализацией интерфейсов и в процессе тестирования у нас нет потребности рассматривать внутреннюю структуру компонентов</li><li>Тесты черного ящика</li><li>Цель: проверка соответствия проектируемых единиц функциональным, приёмным и требованиям надежности</li><li>Для автоматизации интеграционного тестирования применяются системы непрерывной интеграции. Автоматические интеграционные тесты выполняются сразу же после внесения изменений, что позволяет обнаруживать и устранять ошибки в короткие сроки</li></ul><h3 id="подходы" tabindex="-1">Подходы <a class="header-anchor" href="#подходы" aria-label="Permalink to &quot;Подходы&quot;">​</a></h3><ul><li>Снизу вверх (Bottom Up Integration) Все низкоуровневые модули, процедуры или функции собираются воедино и затем тестируются. После чего собирается следующий уровень модулей для проведения интеграционного тестирования. Данный подход считается полезным, если все или практически все модули, разрабатываемого уровня, готовы. Также данный подход помогает определить по результатам тестирования уровень готовности приложения</li><li>Сверху вниз (Top Down Integration) Вначале тестируются все высокоуровневые модули, и постепенно один за другим добавляются низкоуровневые. Все модули более низкого уровня симулируются заглушками с аналогичной функциональностью, затем по мере готовности они заменяются реальными активными компонентами</li><li>Большой взрыв (&quot;Big Bang&quot; Integration) Все или практически все разработанные модули собираются вместе в виде законченной системы или ее основной части, и затем проводится интеграционное тестирование. Такой подход очень хорош для сохранения времени. Однако если тест кейсы и их результаты записаны не верно, то сам процесс интеграции сильно осложнится, что станет преградой для команды тестирования при достижении основной цели интеграционного тестирования</li></ul><h3 id="уровни-интеграционного-тестирования" tabindex="-1">Уровни интеграционного тестирования <a class="header-anchor" href="#уровни-интеграционного-тестирования" aria-label="Permalink to &quot;Уровни интеграционного тестирования&quot;">​</a></h3><ul><li>Компонентный интеграционный уровень (Component Integration testing) Проверяется взаимодействие между компонентами системы после проведения компонентного тестирования</li><li>Системный интеграционный уровень (System Integration Testing) Проверяется взаимодействие между разными системами после проведения системного тестирования</li></ul>',6)])])}const u=i(o,[["render",r]]);export{_ as __pageData,u as default};
